+                            isSelected(object.id) &&
+                            selectedTool === 'select' &&
+                            !object.isLocked &&
+                            !isMultiSelect &&
+                            !hideSelectionFrame &&
+                            !isReadOnly
+                          }
+                          onClick={(e) => {
+                            if (!object.isLocked) {
+                              const isCtrlOrCmd = e.evt.metaKey || e.evt.ctrlKey;
+                              if (isCtrlOrCmd) {
+                                if (isSelected(object.id)) {
+                                  removeFromSelection(object.id);
+                                } else {
+                                  addToSelection({
+                                    type: 'video',
+                                    id: object.id
+                                  });
+                                }
+                              } else {
+                                selectVideo(object.id);
+                              }
+                            }
+                          }}
+                          onDragEnd={(e) =>
+                            handleVideoDragEnd(e, object.id)
+                          }
+                          onTransformEnd={(e) =>
+                            handleVideoTransformEnd(e, object.id)
+                          }
+                          onUploadClick={() => {
+                            setPendingVideoPlaceholderId(object.id);
+                            videoFileInputRef.current?.click();
+                          }}
+                        />
+                      );
+                    }
+                    // Render actual video with playback controls
+                    return (
+                      <VideoNode
+                        key={object.id}
+                        id={object.id}
+                        video={object}
+                        isSelected={isSelected(object.id)}
+                        isMultiSelect={isMultiSelect}
+                        draggable={
+                          isSelected(object.id) &&
+                          selectedTool === 'select' &&
+                          !object.isLocked &&
+                          !isReadOnly
+                        }
+                        showTransformer={
+                          isSelected(object.id) &&
+                          selectedTool === 'select' &&
+                          !object.isLocked &&
+                          !isMultiSelect &&
+                          !hideSelectionFrame &&
+                          !isReadOnly
+                        }
+                        onClick={(e) => {
+                          if (!object.isLocked) {
+                            const isCtrlOrCmd = e.evt.metaKey || e.evt.ctrlKey;
+                            if (isCtrlOrCmd) {
+                              if (isSelected(object.id)) {
+                                removeFromSelection(object.id);
+                              } else {
+                                addToSelection({
+                                  type: 'video',
+                                  id: object.id
+                                });
+                              }
+                            } else {
+                              selectVideo(object.id);
+                            }
+                          }
+                        }}
+                        onPlaybackStateChange={(newIsPlaying) => {
+                          updateTempCanvasObjects((prev) =>
+                            prev.map((obj) =>
+                              obj.id === object.id
+                                ? { ...obj, isPlaying: newIsPlaying }
+                                : obj
+                            )
+                          );
+                        }}
+                        onDragEnd={(e) => handleVideoDragEnd(e, object.id)}
+                        onTransformEnd={(e) =>
+                          handleVideoTransformEnd(e, object.id)
+                        }
+                      />
+                    );
                   }
                   return null;
                 })}
