diff --git a/components/canvas/konva/video-node.tsx b/components/canvas/konva/video-node.tsx
new file mode 100644
index 0000000..8ffc338
--- /dev/null
+++ b/components/canvas/konva/video-node.tsx
@@ -0,0 +1,451 @@
+'use client';
+
+import React, { useRef, useEffect, useState, useCallback } from 'react';
+import { Group, Image as KonvaImage, Rect, Transformer, Path, Text } from 'react-konva';
+import Konva from 'konva';
+import { KonvaEventObject } from 'konva/lib/Node';
+
+import { VideoObject } from '@/components/canvas/types';
+
+// Rounded play icon path (viewBox: 0 0 24 24)
+// Based on Lucide Play icon with ~2 unit corner radius using quadratic Bézier curves
+// Original vertices: (6,3), (20,12), (6,21)
+const PLAY_ICON_PATH = 'M6 5 Q6 3 7.7 4.1 L18.3 10.9 Q20 12 18.3 13.1 L7.7 19.9 Q6 21 6 19 Z';
+
+export interface VideoNodeProps {
+  id?: string;
+  video: VideoObject;
+  isSelected: boolean;
+  isMultiSelect?: boolean;
+  opacity?: number;
+  draggable?: boolean;
+  showTransformer?: boolean;
+  onClick?: (e: Konva.KonvaEventObject<MouseEvent>) => void;
+  onDragEnd?: (e: Konva.KonvaEventObject<DragEvent>) => void;
+  onTransformEnd?: (e: Konva.KonvaEventObject<Event>) => void;
+  onDragMove?: (e: Konva.KonvaEventObject<DragEvent>) => void;
+  onPlaybackStateChange?: (isPlaying: boolean) => void;
+  onTimeUpdate?: (currentTime: number) => void;
+}
+
+const VideoNode: React.FC<VideoNodeProps> = ({
+  id,
+  video,
+  isSelected,
+  isMultiSelect,
+  opacity = 1,
+  draggable,
+  showTransformer,
+  onClick,
+  onDragEnd,
+  onTransformEnd,
+  onDragMove,
+  onPlaybackStateChange,
+  onTimeUpdate
+}) => {
+  const groupRef = useRef<Konva.Group>(null);
+  const imageRef = useRef<Konva.Image>(null);
+  const transformerRef = useRef<Konva.Transformer>(null);
+  const videoRef = useRef<HTMLVideoElement | null>(null);
+  const animationRef = useRef<Konva.Animation | null>(null);
+
+  // Stable refs for callbacks to prevent unnecessary video element recreation
+  const onPlaybackStateChangeRef = useRef(onPlaybackStateChange);
+  const onTimeUpdateRef = useRef(onTimeUpdate);
+  onPlaybackStateChangeRef.current = onPlaybackStateChange;
+  onTimeUpdateRef.current = onTimeUpdate;
+
+  const [isVideoReady, setIsVideoReady] = useState(false);
+  const [posterImage, setPosterImage] = useState<HTMLImageElement | null>(null);
+  const [dragStartPos, setDragStartPos] = useState<{
+    x: number;
+    y: number;
+  } | null>(null);
+  const [isShiftPressed, setIsShiftPressed] = useState(false);
+
+  const { width, height, rotation, src, poster, isPlaying, volume, isMuted, loop } =
+    video;
+
+  // Calculate dynamic icon size based on video dimensions (matches VideoPlaceholderNode)
+  const iconSize = Math.min(width, height) * 0.3;
+  const iconX = (width - iconSize) / 2;
+  const iconY = (height - iconSize) / 2;
+
+  // Load poster image from data URL for immediate display
+  useEffect(() => {
+    if (!poster) {
+      setPosterImage(null);
+      return;
+    }
+
+    const img = new Image();
+    img.onload = () => {
+      setPosterImage(img);
+      // Force layer redraw to show poster
+      imageRef.current?.getLayer()?.batchDraw();
+    };
+    img.src = poster;
+
+    return () => {
+      setPosterImage(null);
+    };
+  }, [poster]);
+
+  // Initialize video element - only recreate when src changes
+  useEffect(() => {
+    const videoElement = document.createElement('video');
+    videoElement.src = src;
+    videoElement.crossOrigin = 'anonymous';
+    videoElement.loop = loop ?? false;
+    videoElement.muted = isMuted ?? true; // Default muted for autoplay policy
+    videoElement.volume = volume ?? 1;
+    videoElement.playsInline = true;
+    videoElement.preload = 'auto'; // Ensure first frame is loaded
+
+    // Use loadeddata instead of loadedmetadata to ensure first frame is decoded
+    videoElement.addEventListener('loadeddata', () => {
+      setIsVideoReady(true);
+      // Force layer redraw to show video frame
+      imageRef.current?.getLayer()?.batchDraw();
+    });
+
+    videoElement.addEventListener('timeupdate', () => {
+      onTimeUpdateRef.current?.(videoElement.currentTime);
+    });
+
+    videoElement.addEventListener('ended', () => {
+      if (!videoElement.loop) {
+        onPlaybackStateChangeRef.current?.(false);
+      }
+    });
+
+    videoRef.current = videoElement;
+
+    return () => {
+      videoElement.pause();
+      videoElement.src = '';
+      videoRef.current = null;
+    };
+  }, [src]); // Only depend on src - other properties are updated in separate effect
+
+  // Handle play/pause state changes
+  useEffect(() => {
+    const videoElement = videoRef.current;
+
+    if (!videoElement) return;
+
+    if (isPlaying) {
+      videoElement.play().catch(console.error);
+    } else {
+      videoElement.pause();
+    }
+  }, [isPlaying]);
+
+  // Handle animation loop for canvas redraw (separate from play/pause)
+  useEffect(() => {
+    const layer = imageRef.current?.getLayer();
+
+    if (!layer || !isVideoReady) return;
+
+    if (isPlaying) {
+      // Start animation loop to redraw video frames
+      if (!animationRef.current) {
+        animationRef.current = new Konva.Animation(() => {
+          // Animation callback triggers layer redraw
+        }, layer);
+      }
+      animationRef.current.start();
+    } else {
+      animationRef.current?.stop();
+    }
+
+    return () => {
+      animationRef.current?.stop();
+    };
+  }, [isPlaying, isVideoReady]);
+
+  // Update video properties when they change
+  useEffect(() => {
+    if (videoRef.current) {
+      videoRef.current.volume = volume ?? 1;
+      videoRef.current.muted = isMuted ?? false;
+      videoRef.current.loop = loop ?? false;
+    }
+  }, [volume, isMuted, loop]);
+
+  // Shift key handling for constrained drag
+  useEffect(() => {
+    const handleKeyDown = (e: KeyboardEvent) => {
+      if (e.key === 'Shift') setIsShiftPressed(true);
+    };
+    const handleKeyUp = (e: KeyboardEvent) => {
+      if (e.key === 'Shift') setIsShiftPressed(false);
+    };
+    window.addEventListener('keydown', handleKeyDown);
+    window.addEventListener('keyup', handleKeyUp);
+    return () => {
+      window.removeEventListener('keydown', handleKeyDown);
+      window.removeEventListener('keyup', handleKeyUp);
+    };
+  }, []);
+
+  // Attach transformer
+  useEffect(() => {
+    if (!showTransformer || !transformerRef.current || !groupRef.current) {
+      return;
+    }
+    transformerRef.current.nodes([groupRef.current]);
+    transformerRef.current.moveToTop();
+    transformerRef.current.getLayer()?.batchDraw();
+  }, [showTransformer]);
+
+  const handleDragStart = () => {
+    if (groupRef.current) {
+      setDragStartPos({ x: groupRef.current.x(), y: groupRef.current.y() });
+    }
+  };
+
+  const handleDragEnd = (e: KonvaEventObject<DragEvent>) => {
+    onDragEnd?.(e);
+  };
+
+  const handleTransformEnd = (e: KonvaEventObject<Event>) => {
+    onTransformEnd?.(e);
+  };
+
+  // Hover-to-play: start playing when mouse enters
+  const handleMouseEnter = useCallback(() => {
+    if (!isPlaying) {
+      onPlaybackStateChange?.(true);
+    }
+  }, [isPlaying, onPlaybackStateChange]);
+
+  // Hover-to-play: stop playing when mouse leaves
+  const handleMouseLeave = useCallback(() => {
+    if (isPlaying) {
+      onPlaybackStateChange?.(false);
+    }
+  }, [isPlaying, onPlaybackStateChange]);
+
+  // Touch devices: tap to toggle play/pause (since hover doesn't work)
+  const handleTap = useCallback(
+    (e: KonvaEventObject<TouchEvent>) => {
+      // Call original onClick handler if provided
+      onClick?.(e as unknown as KonvaEventObject<MouseEvent>);
+      // Toggle play state
+      onPlaybackStateChange?.(!isPlaying);
+    },
+    [isPlaying, onPlaybackStateChange, onClick]
+  );
+
+  const groupProps = {
+    x: video.position.x,
+    y: video.position.y,
+    width,
+    height,
+    opacity,
+    rotation,
+    scaleX: video.scaleX ?? 1,
+    scaleY: video.scaleY ?? 1,
+    draggable,
+    onDragStart: handleDragStart,
+    onDragEnd: handleDragEnd,
+    onDragMove,
+    onClick,
+    onTap: handleTap,
+    onMouseEnter: handleMouseEnter,
+    onMouseLeave: handleMouseLeave,
+    onTransformEnd: handleTransformEnd,
+    dragBoundFunc: (pos: Konva.Vector2d) => {
+      if (!isShiftPressed || !dragStartPos) {
+        return pos;
+      }
+      const dx = Math.abs(pos.x - dragStartPos.x);
+      const dy = Math.abs(pos.y - dragStartPos.y);
+      if (dx > dy) {
+        return { x: pos.x, y: dragStartPos.y };
+      } else {
+        return { x: dragStartPos.x, y: pos.y };
+      }
+    }
+  };
+
+  return (
+    <>
+      <Group ref={groupRef} id={video.id} {...groupProps}>
+        {/* Video display - show poster while loading, then video frame */}
+        {isVideoReady && videoRef.current ? (
+          <KonvaImage
+            ref={imageRef}
+            image={videoRef.current}
+            width={width}
+            height={height}
+          />
+        ) : posterImage ? (
+          // Show poster image while video loads
+          <KonvaImage
+            ref={imageRef}
+            image={posterImage}
+            width={width}
+            height={height}
+          />
+        ) : (
+          // Fallback placeholder if no poster
+          <Rect
+            width={width}
+            height={height}
+            fill="#1a1a2e"
+            cornerRadius={4}
+          />
+        )}
+
+        {/* Play indicator overlay when paused - using same icon style as placeholder */}
+        {!isPlaying && (isVideoReady || posterImage) && (
+          <Group x={iconX} y={iconY}>
+            {/* Play icon - using same Lucide icon path and sizing as VideoPlaceholderNode */}
+            <Path
+              data={PLAY_ICON_PATH}
+              x={iconSize * 0.35}
+              y={iconSize * 0.25}
+              scaleX={(iconSize / 24) * 0.5}
+              scaleY={(iconSize / 24) * 0.5}
+              fill="rgba(59, 130, 246, 0.9)"
+            />
+          </Group>
+        )}
+
+        {/* Upload indicator overlay */}
+        {video.isUploading && (
+          <Group listening={false}>
+            {/* Semi-transparent backdrop */}
+            <Rect
+              width={width}
+              height={height}
+              fill="rgba(0, 0, 0, 0.5)"
+              cornerRadius={4}
+            />
+            {/* Uploading text */}
+            <Text
+              text="Uploading..."
+              x={0}
+              y={height / 2 - 10}
+              width={width}
+              align="center"
+              fontSize={Math.min(width, height) * 0.08}
+              fill="white"
+              fontStyle="bold"
+            />
+          </Group>
+        )}
+
+        {/* Multi-select indicator */}
+        {isMultiSelect && isSelected && (
+          <Rect
+            width={width}
+            height={height}
+            stroke="#007bff"
+            strokeWidth={2}
+            fill="transparent"
+            listening={false}
+          />
+        )}
+      </Group>
+
+      {/* Transformer for single selection */}
+      {showTransformer && !isMultiSelect && (
+        <Transformer
+          ref={transformerRef}
+          id={`transformer-video-${id}`}
+          boundBoxFunc={(oldBox, newBox) => {
+            if (newBox.width < 50 || newBox.height < 50) {
+              return oldBox;
+            }
+            return newBox;
+          }}
+          rotationSnaps={[0, 45, 90, 135, 180, 225, 270, 315]}
+          rotationSnapTolerance={10}
+          resizeEnabled={true}
+          centeredScaling={false}
+          keepRatio={true}
+          anchorStroke="#007bff"
+          anchorFill="#ffffff"
+          anchorSize={8}
+          borderStroke="#007bff"
+          borderStrokeWidth={1.5}
+          onTransformEnd={handleTransformEnd}
+        />
+      )}
+    </>
+  );
+};
+
+export default VideoNode;
+
+/* Video Preview Component - for layer thumbnails, etc. */
+export const VideoPreviewNode: React.FC<
+  Omit<
+    VideoNodeProps,
+    | 'id'
+    | 'isSelected'
+    | 'isMultiSelect'
+    | 'draggable'
+    | 'showTransformer'
+    | 'onClick'
+    | 'onDragEnd'
+    | 'onTransformEnd'
+    | 'onDragMove'
+    | 'onPlaybackStateChange'
+    | 'onTimeUpdate'
+  >
+> = ({ video, opacity = 1 }) => {
+  const videoRef = useRef<HTMLVideoElement | null>(null);
+  const [isVideoReady, setIsVideoReady] = useState(false);
+
+  const { width, height, rotation, src, poster } = video;
+
+  // Initialize video element for preview (paused, showing poster or first frame)
+  useEffect(() => {
+    const videoElement = document.createElement('video');
+    videoElement.src = src;
+    videoElement.crossOrigin = 'anonymous';
+    videoElement.muted = true;
+    videoElement.preload = 'metadata';
+
+    if (poster) {
+      videoElement.poster = poster;
+    }
+
+    videoElement.addEventListener('loadeddata', () => {
+      setIsVideoReady(true);
+    });
+
+    videoRef.current = videoElement;
+
+    return () => {
+      videoElement.src = '';
+      videoRef.current = null;
+    };
+  }, [src, poster]);
+
+  const groupProps = {
+    x: video.position.x,
+    y: video.position.y,
+    width,
+    height,
+    opacity,
+    rotation,
+    scaleX: video.scaleX ?? 1,
+    scaleY: video.scaleY ?? 1,
+    draggable: false
+  };
+
+  return (
+    <Group id={video.id} {...groupProps}>
+      {isVideoReady && videoRef.current ? (
+        <KonvaImage image={videoRef.current} width={width} height={height} />
+      ) : (
+        <Rect width={width} height={height} fill="#1a1a2e" cornerRadius={4} />
+      )}
+    </Group>
+  );
+};
