+'use client';
+
+import React, { useRef, useEffect, useState } from 'react';
+import { Group, Rect, Transformer, Path } from 'react-konva';
+import Konva from 'konva';
+import { KonvaEventObject } from 'konva/lib/Node';
+
+import { VideoObject } from '@/components/canvas/types';
+
+// Upload icon path (viewBox: 0 0 24 24) - based on Lucide Upload icon
+// Combined path: upload arrow (M21 15v4...) + vertical line (M12 3v12) + arrow head (M17 8l-5-5-5 5)
+const UPLOAD_ICON_PATH = 'M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4 M17 8l-5-5-5 5 M12 3v12';
+
+export interface VideoPlaceholderNodeProps {
+  id?: string;
+  video: VideoObject;
+  isSelected: boolean;
+  isMultiSelect?: boolean;
+  opacity?: number;
+  draggable?: boolean;
+  showTransformer?: boolean;
+  onClick?: (e: Konva.KonvaEventObject<MouseEvent>) => void;
+  onDragEnd?: (e: Konva.KonvaEventObject<DragEvent>) => void;
+  onTransformEnd?: (e: Konva.KonvaEventObject<Event>) => void;
+  onDragMove?: (e: Konva.KonvaEventObject<DragEvent>) => void;
+  onUploadClick?: () => void;
+}
+
+const VideoPlaceholderNode: React.FC<VideoPlaceholderNodeProps> = ({
+  id,
+  video,
+  isSelected,
+  isMultiSelect,
+  opacity = 1,
+  draggable,
+  showTransformer,
+  onClick,
+  onDragEnd,
+  onTransformEnd,
+  onDragMove,
+  onUploadClick
+}) => {
+  const groupRef = useRef<Konva.Group>(null);
+  const transformerRef = useRef<Konva.Transformer>(null);
+
+  const [dragStartPos, setDragStartPos] = useState<{
+    x: number;
+    y: number;
+  } | null>(null);
+  const [isShiftPressed, setIsShiftPressed] = useState(false);
+  const [didDrag, setDidDrag] = useState(false);
+
+  const { width, height, rotation } = video;
+
+  // Shift key handling for constrained drag
+  useEffect(() => {
+    const handleKeyDown = (e: KeyboardEvent) => {
+      if (e.key === 'Shift') setIsShiftPressed(true);
+    };
+    const handleKeyUp = (e: KeyboardEvent) => {
+      if (e.key === 'Shift') setIsShiftPressed(false);
+    };
+    window.addEventListener('keydown', handleKeyDown);
+    window.addEventListener('keyup', handleKeyUp);
+    return () => {
+      window.removeEventListener('keydown', handleKeyDown);
+      window.removeEventListener('keyup', handleKeyUp);
+    };
+  }, []);
+
+  // Attach transformer
+  useEffect(() => {
+    if (!showTransformer || !transformerRef.current || !groupRef.current) {
+      return;
+    }
+    transformerRef.current.nodes([groupRef.current]);
+    transformerRef.current.moveToTop();
+    transformerRef.current.getLayer()?.batchDraw();
+  }, [showTransformer]);
+
+  const handleDragStart = () => {
+    setDidDrag(true);
+    if (groupRef.current) {
+      setDragStartPos({ x: groupRef.current.x(), y: groupRef.current.y() });
+    }
+  };
+
+  const handleDragEnd = (e: KonvaEventObject<DragEvent>) => {
+    onDragEnd?.(e);
+    // Reset drag flag asynchronously so the click handler sees didDrag=true
+    // and ignores the post-drag click, but subsequent clicks work normally
+    setTimeout(() => setDidDrag(false), 0);
+  };
+
+  const handleTransformEnd = (e: KonvaEventObject<Event>) => {
+    onTransformEnd?.(e);
+  };
+
+  const handleClick = (e: Konva.KonvaEventObject<MouseEvent>) => {
+    onClick?.(e);
+    // Only trigger upload if this was a pure click, not a drag
+    if (!didDrag) {
+      onUploadClick?.();
+    }
+  };
+
+  const groupProps = {
+    x: video.position.x,
+    y: video.position.y,
+    width,
+    height,
+    opacity,
+    rotation,
+    scaleX: video.scaleX ?? 1,
+    scaleY: video.scaleY ?? 1,
+    draggable,
+    onDragStart: handleDragStart,
+    onDragEnd: handleDragEnd,
+    onDragMove,
+    onClick: handleClick,
+    onTap: handleClick,
+    onTransformEnd: handleTransformEnd,
+    dragBoundFunc: (pos: Konva.Vector2d) => {
+      if (!isShiftPressed || !dragStartPos) {
+        return pos;
+      }
+      const dx = Math.abs(pos.x - dragStartPos.x);
+      const dy = Math.abs(pos.y - dragStartPos.y);
+      if (dx > dy) {
+        return { x: pos.x, y: dragStartPos.y };
+      } else {
+        return { x: dragStartPos.x, y: pos.y };
+      }
+    }
+  };
+
+  // Calculate icon size based on placeholder dimensions
+  const iconSize = Math.min(width, height) * 0.3;
+  const iconX = (width - iconSize) / 2;
+  const iconY = (height - iconSize) / 2;
+
+  return (
+    <>
+      <Group ref={groupRef} id={video.id} {...groupProps}>
+        {/* Liquid glass background */}
+        <Rect
+          width={width}
+          height={height}
+          fill="rgba(255, 255, 255, 0.1)"
+          cornerRadius={8}
+          shadowColor="rgba(0, 0, 0, 0.25)"
+          shadowBlur={20}
+          shadowOffsetY={4}
+        />
+
+        {/* Inner frosted glass effect */}
+        <Rect
+          x={4}
+          y={4}
+          width={width - 8}
+          height={height - 8}
+          fill="#7287fd99" // catppuccin Lavender
+          cornerRadius={6}
+        />
+
+        {/* Video icon - upload arrow */}
+        <Group x={iconX} y={iconY}>
+          {/* Upload icon - using Lucide icon path (stroke-based) */}
+          <Path
+            data={UPLOAD_ICON_PATH}
+            x={iconSize * 0.25}
+            y={iconSize * 0.25}
+            scaleX={(iconSize / 24) * 0.5}
+            scaleY={(iconSize / 24) * 0.5}
+            stroke="rgba(59, 130, 246, 0.9)"
+            strokeWidth={4}
+            lineCap="round"
+            lineJoin="round"
+          />
+        </Group>
+
+{/* Click anywhere on placeholder to upload a video */}
+
+        {/* Multi-select indicator */}
+        {isMultiSelect && isSelected && (
+          <Rect
+            width={width}
+            height={height}
+            stroke="#007bff"
+            strokeWidth={2}
+            fill="transparent"
+            listening={false}
+            cornerRadius={8}
+          />
+        )}
+      </Group>
+
+      {/* Transformer for single selection */}
+      {showTransformer && !isMultiSelect && (
+        <Transformer
+          ref={transformerRef}
+          id={`transformer-video-placeholder-${id}`}
+          boundBoxFunc={(oldBox, newBox) => {
+            if (newBox.width < 50 || newBox.height < 50) {
+              return oldBox;
+            }
+            return newBox;
+          }}
+          rotationSnaps={[0, 45, 90, 135, 180, 225, 270, 315]}
+          rotationSnapTolerance={10}
+          resizeEnabled={true}
+          centeredScaling={false}
+          keepRatio={true}
+          anchorStroke="#007bff"
+          anchorFill="#ffffff"
+          anchorSize={8}
+          borderStroke="#007bff"
+          borderStrokeWidth={1.5}
+          onTransformEnd={handleTransformEnd}
+        />
+      )}
+    </>
+  );
+};
+
+export default VideoPlaceholderNode;
