diff --git a/lib/video/extract-frame.ts b/lib/video/extract-frame.ts
new file mode 100644
index 0000000..2320556
--- /dev/null
+++ b/lib/video/extract-frame.ts
@@ -0,0 +1,146 @@
+/**
+ * Options for extracting a frame from a video element.
+ */
+export interface ExtractFrameOptions {
+  /** JPEG quality 0-1 (default: 0.8) */
+  quality?: number;
+  /** Scale down videos wider than this */
+  maxWidth?: number;
+  /** Scale down videos taller than this */
+  maxHeight?: number;
+  /** Timeout for seeking in milliseconds (default: 3000ms) */
+  seekTimeout?: number;
+}
+
+const DEFAULT_QUALITY = 0.8;
+const DEFAULT_SEEK_TIMEOUT = 3000;
+
+/**
+ * Extracts the first frame of a video as a JPEG data URL.
+ *
+ * @param video - The HTMLVideoElement to extract a frame from
+ * @param options - Configuration options for the extraction
+ * @returns A data URL string of the frame, or null if extraction fails
+ *
+ * @example
+ * ```ts
+ * const video = document.createElement('video');
+ * video.src = blobUrl;
+ * video.onloadeddata = async () => {
+ *   const poster = await extractVideoFrame(video, { maxWidth: 640 });
+ *   if (poster) {
+ *     // Use poster as thumbnail
+ *   }
+ * };
+ * ```
+ */
+export async function extractVideoFrame(
+  video: HTMLVideoElement,
+  options: ExtractFrameOptions = {}
+): Promise<string | null> {
+  const {
+    quality = DEFAULT_QUALITY,
+    maxWidth,
+    maxHeight,
+    seekTimeout = DEFAULT_SEEK_TIMEOUT
+  } = options;
+
+  // Validate video has loaded enough data
+  // readyState >= 2 (HAVE_CURRENT_DATA) means we have at least one frame
+  if (video.readyState < 2) {
+    return null;
+  }
+
+  const { videoWidth, videoHeight } = video;
+
+  // Validate video has dimensions
+  if (!videoWidth || !videoHeight) {
+    return null;
+  }
+
+  try {
+    // Seek to beginning if not already there
+    if (video.currentTime !== 0) {
+      await seekToStart(video, seekTimeout);
+    }
+
+    // Calculate scaled dimensions
+    const { width, height } = calculateDimensions(
+      videoWidth,
+      videoHeight,
+      maxWidth,
+      maxHeight
+    );
+
+    // Create canvas and draw frame
+    const canvas = document.createElement('canvas');
+    canvas.width = width;
+    canvas.height = height;
+
+    const ctx = canvas.getContext('2d');
+    if (!ctx) {
+      return null;
+    }
+
+    ctx.drawImage(video, 0, 0, width, height);
+
+    // Convert to data URL
+    return canvas.toDataURL('image/jpeg', quality);
+  } catch {
+    // Handle CORS errors, tainted canvas, or other failures gracefully
+    return null;
+  }
+}
+
+/**
+ * Seeks video to the start and waits for the seek to complete.
+ */
+function seekToStart(
+  video: HTMLVideoElement,
+  timeout: number
+): Promise<void> {
+  return new Promise((resolve) => {
+    const onSeeked = () => {
+      video.removeEventListener('seeked', onSeeked);
+      clearTimeout(timeoutId);
+      resolve();
+    };
+
+    const timeoutId = setTimeout(() => {
+      video.removeEventListener('seeked', onSeeked);
+      resolve(); // Resolve anyway on timeout - we'll try to capture current frame
+    }, timeout);
+
+    video.addEventListener('seeked', onSeeked);
+    video.currentTime = 0;
+  });
+}
+
+/**
+ * Calculates final dimensions respecting max constraints while maintaining aspect ratio.
+ */
+function calculateDimensions(
+  videoWidth: number,
+  videoHeight: number,
+  maxWidth?: number,
+  maxHeight?: number
+): { width: number; height: number } {
+  let width = videoWidth;
+  let height = videoHeight;
+
+  // Apply maxWidth constraint
+  if (maxWidth && width > maxWidth) {
+    const scale = maxWidth / width;
+    width = maxWidth;
+    height = Math.round(height * scale);
+  }
+
+  // Apply maxHeight constraint
+  if (maxHeight && height > maxHeight) {
+    const scale = maxHeight / height;
+    height = maxHeight;
+    width = Math.round(width * scale);
+  }
+
+  return { width, height };
+}
